const items = $input.all();
const transactions = items.filter(i => i.json.transaction_id !== undefined && String(i.json.transaction_id).trim() !== "").map(i => i.json);
const members = items.filter(i => i.json.transaction_id === undefined && i.json.member_id !== undefined).map(i => i.json);

// ===== Parameter rule (ubah di sini bila SOP berubah) =====
const OPERATING_HOUR_START = 9;
const OPERATING_HOUR_END = 21; // transaksi pukul 21:xx masih dianggap dalam jam operasional
const IMPOSSIBLE_TRAVEL_MINUTES = 90;
const TIER_QTY_LIMIT = { platinum: 1, gold: 2 };
const TIER_RANK = { regular: 0, silver: 1, gold: 2, platinum: 3 };

const norm = v => (v === undefined || v === null) ? "" : String(v).trim();
const rank = tier => { const k = norm(tier).toLowerCase(); return Object.prototype.hasOwnProperty.call(TIER_RANK, k) ? TIER_RANK[k] : -1; };
const cityOf = t => norm(t.store_city || t.geo_area);
const isOnline = t => norm(t.channel).toLowerCase() === "online" || cityOf(t).toLowerCase() === "online";
const cardKeyOf = t => {
  if (norm(t.card_key)) return norm(t.card_key);
  const last4 = norm(t.card_last4);
  return last4 ? last4 + "|" + norm(t.issuing_bank).toUpperCase() : "";
};
const parseTime = v => { const d = new Date(norm(v).replace(" ", "T")); return isNaN(d.getTime()) ? null : d; };
const pushUnique = (obj, key, val) => { if (!obj[key]) obj[key] = []; if (obj[key].indexOf(val) === -1) obj[key].push(val); };

// ===== Master member =====
const memberById = {};
members.forEach(m => { const id = norm(m.member_id); if (id) memberById[id] = m; });

// ===== R6: kontak duplikat (telepon dinormalisasi ke digit, email lowercase) =====
const phoneGroups = {};
const emailGroups = {};
members.forEach(m => {
  const id = norm(m.member_id);
  if (!id) return;
  const phone = norm(m.phone_number).replace(/\D/g, "");
  const email = norm(m.email).toLowerCase();
  if (phone) pushUnique(phoneGroups, phone, id);
  if (email) pushUnique(emailGroups, email, id);
});
const duplicateEvidence = {};
const collectDup = (groups, label) => Object.keys(groups).forEach(k => {
  const ids = groups[k];
  if (ids.length < 2) return;
  ids.forEach(id => pushUnique(duplicateEvidence, id, label + " sama dengan member " + ids.filter(x => x !== id).join(", ")));
});
collectDup(phoneGroups, "nomor telepon");
collectDup(emailGroups, "email");

// ===== R1: kartu dipakai >1 member (hanya jika card_key / card_last4 tersedia) =====
const cardGroups = {};
transactions.forEach(t => {
  const key = cardKeyOf(t);
  const mid = norm(t.member_id);
  if (key && mid) pushUnique(cardGroups, key, mid);
});

// ===== R5: impossible travel antar kota fisik =====
const byMember = {};
transactions.forEach(t => { const mid = norm(t.member_id); if (mid) { if (!byMember[mid]) byMember[mid] = []; byMember[mid].push(t); } });
const travelEvidence = {};
Object.keys(byMember).forEach(mid => {
  const list = byMember[mid].filter(t => parseTime(t.transaction_datetime)).sort((a, b) => parseTime(a.transaction_datetime) - parseTime(b.transaction_datetime));
  for (let i = 1; i < list.length; i++) {
    const prev = list[i - 1];
    const curr = list[i];
    if (isOnline(prev) || isOnline(curr)) continue;
    const prevCity = cityOf(prev);
    const currCity = cityOf(curr);
    if (!prevCity || !currCity || prevCity.toLowerCase() === currCity.toLowerCase()) continue;
    const diff = (parseTime(curr.transaction_datetime) - parseTime(prev.transaction_datetime)) / 60000;
    if (diff >= 0 && diff < IMPOSSIBLE_TRAVEL_MINUTES) {
      const ev = prevCity + " pada " + prev.transaction_datetime + " lalu " + currCity + " pada " + curr.transaction_datetime + " (selisih " + Math.round(diff) + " menit)";
      pushUnique(travelEvidence, norm(prev.transaction_id), ev);
      pushUnique(travelEvidence, norm(curr.transaction_id), ev);
    }
  }
});

const hourOf = t => {
  const h = Number(t.transaction_hour);
  if (norm(t.transaction_hour) !== "" && !isNaN(h)) return h;
  const m = norm(t.transaction_datetime).match(/[T ](\d{1,2}):/);
  return m ? Number(m[1]) : null;
};

const verifiedAt = new Date().toISOString();
return transactions.map(t => {
  const tid = norm(t.transaction_id);
  const mid = norm(t.member_id);

  const cardKey = cardKeyOf(t);
  const sharers = cardKey ? (cardGroups[cardKey] || []).filter(id => id !== mid) : [];
  const r1 = sharers.length > 0;

  const memberTier = (memberById[mid] && memberById[mid].member_tier) || t.member_tier;
  const itemRank = rank(t.item_tier_requirement);
  const r2 = itemRank > 0 && itemRank > rank(memberTier);

  const hour = hourOf(t);
  const r3 = hour !== null && (hour < OPERATING_HOUR_START || hour > OPERATING_HOUR_END);

  const tierKey = norm(t.item_tier_requirement).toLowerCase();
  const qty = Number(t.qty) || 0;
  const qtyLimit = TIER_QTY_LIMIT[tierKey];
  const r4 = qtyLimit !== undefined && qty > qtyLimit;

  const r5 = Boolean(travelEvidence[tid]);
  const r6 = Boolean(mid && duplicateEvidence[mid]);

  const rules = [
    { code: "R1", flag: r1, field: "flag_R1_card_sharing", ev: r1 ? "Kartu yang sama juga dipakai oleh member " + sharers.join(", ") : "Tidak ada indikasi kartu dipakai member lain pada batch ini" },
    { code: "R2", flag: r2, field: "flag_R2_tier_mismatch", ev: r2 ? "Item membutuhkan tier " + t.item_tier_requirement + " namun member bertier " + (memberTier || "tidak diketahui") : "Tier item sesuai atau di bawah tier member" },
    { code: "R3", flag: r3, field: "flag_R3_outside_hours", ev: r3 ? "Transaksi pukul " + hour + ":00, di luar jam operasional " + OPERATING_HOUR_START + ":00-" + OPERATING_HOUR_END + ":59" : "Transaksi dalam jam operasional" },
    { code: "R4", flag: r4, field: "flag_R4_bulk_limited", ev: r4 ? "Item " + t.item_tier_requirement + " dibeli " + qty + " pcs, melebihi batas " + qtyLimit : "Kuantitas dalam batas wajar" },
    { code: "R5", flag: r5, field: "flag_R5_impossible_travel", ev: r5 ? travelEvidence[tid].join("; ") : "Tidak ada transaksi lain dari member ini di kota berbeda dalam waktu singkat" },
    { code: "R6", flag: r6, field: "flag_R6_duplicate_account", ev: r6 ? duplicateEvidence[mid].join("; ") : "Tidak ada kontak (telepon/email) yang sama dengan member lain" }
  ];

  const out = Object.assign({}, t);
  rules.forEach(r => { out[r.field] = r.flag; out["evidence_" + r.code] = r.ev; });
  const hits = rules.filter(r => r.flag);
  out.anomaly_count = hits.length;
  out.triggered_rules = hits.map(r => r.code).join(", ");
  out.evidence_summary = hits.map(r => r.code + ": " + r.ev).join("\n");
  out.is_anomaly = hits.length > 0;
  out.is_anomaly_num = hits.length > 0 ? 1 : 0;
  out.verified_at = verifiedAt;
  return { json: out };
});

// Urutkan kandidat paling berisiko dulu: jumlah rule terpicu, lalu nilai transaksi.
const MAX_ALERTS = 3;
return $input.all()
  .map((item, index) => ({ json: item.json, pairedItem: { item: index } }))
  .sort((a, b) => (Number(b.json.anomaly_count) - Number(a.json.anomaly_count)) || ((Number(b.json.net_amount_idr) || 0) - (Number(a.json.net_amount_idr) || 0)))
  .slice(0, MAX_ALERTS);

const original = $("Prioritaskan Kandidat (Top 3)").item.json;
const classified = $json.output || {};
const PRIORITY = { high: "High", medium: "Medium", low: "Low" };
const key = String(classified.priority || "").trim().toLowerCase();
const merged = Object.assign({}, original);
merged.priority = PRIORITY[key] || "Medium";
merged.priority_rationale = classified.rationale || "Output classifier tidak valid; prioritas default Medium dan perlu review manual.";
return { json: merged };

