const original = $("Gabungkan Prioritas").item.json;
const draft = $json.output || {};
const merged = Object.assign({}, original);
merged.alert_subject = draft.subject || ("[Audit Alert - " + original.priority + "] TX " + original.transaction_id + " - " + original.anomaly_count + " indikator anomali");
merged.alert_body_html = draft.body_html || ("<p>Transaksi " + original.transaction_id + " memiliki indikator anomali (" + original.triggered_rules + ") yang memerlukan review.</p><pre>" + original.evidence_summary + "</pre>");
return { json: merged };
